#!/bin/bash
# Generates the Swift helper version constant from helper/VERSION, the single source of
# truth for the helper version. Run by scripts/build-helper.sh, scripts/dev.sh (through
# the build it drives and directly), scripts/check-version.sh, and scripts/verify.sh
# before anything compiles the helper, so the generated file is never edited by hand
# and never committed.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
VERSION_FILE="$ROOT/helper/VERSION"
OUT="$ROOT/helper/Sources/OvernoteCore/GeneratedVersion.swift"

version="$(tr -d '[:space:]' <"$VERSION_FILE")"
if [[ -z "$version" ]]; then
  echo "helper/VERSION is empty" >&2
  exit 1
fi
# Escape the two characters that could break out of the Swift string literal.
version="${version//\\/\\\\}"
version="${version//\"/\\\"}"

mkdir -p "$(dirname "$OUT")"
tmp="$OUT.tmp.$$"
trap 'rm -f "$tmp"' EXIT
cat >"$tmp" <<EOF
// Generated by scripts/generate-helper-version.sh from helper/VERSION. Do not edit by hand.
public extension HelperVersion {
    static let current = "$version"
}
EOF

# Only replace the file when the version actually changed, so watchers that fingerprint
# the sources do not see a fresh modification time on every run.
if [[ -f "$OUT" ]] && cmp -s "$tmp" "$OUT"; then
  rm -f "$tmp"
else
  mv -f "$tmp" "$OUT"
fi
trap - EXIT
